---@module 'hl'

-- See https://wiki.hypr.land/Configuring/Monitors/
--
-- Важно: position задаётся в ЛОГИЧЕСКИХ пикселях (физический размер / scale).
-- Поэтому при scale = 1.25 нельзя оставлять нижний монитор на y=1080:
-- его логическая высота станет 1080 / 1.25 = 864, и между мониторами
-- появится «мёртвая зона», в которую курсор упирается.
-- auto-down ставит второй монитор вплотную под первым уже в логических
-- координатах, поэтому работает при любом масштабе.

hl.monitor({
	output = "HDMI-A-1",
	mode = "1920x1080@60.0 -hsync +vsync",
	position = "0x0",
	scale = 1.25,
})

hl.monitor({
	output = "eDP-1",
	mode = "1920x1080@144.0 -hsync +vsync",
	position = "auto-down",
	scale = 1.25,
})

